import json

catalog_data = json.loads(full_catalog)
orders_data = json.loads(full_orders)
policies_data = json.loads(full_policies)

# Find order
order = None
for o in orders_data:
    if o.get("order_id") == "ORD-5B048F":
        order = o
        break

# Find products
speaker = None
mouse = None
for item in catalog_data:
    if item.get("product_id") in [li.get("product_id") for li in order.get("items", [])]:
        if "speaker" in item.get("name","").lower() or "anker" in item.get("name","").lower():
            speaker = item
        if "mouse" in item.get("name","").lower() or "logitech" in item.get("name","").lower():
            mouse = item

# If not found by product_id, search by name
if not speaker or not mouse:
    for item in catalog_data:
        n = item.get("name","").lower()
        if "anker" in n and "speaker" in n:
            speaker = item
        if "logitech" in n and "mouse" in n and "m310" in n:
            mouse = item

print("Order:", json.dumps(order, indent=2))
print("\nSpeaker:", json.dumps(speaker, indent=2) if speaker else "NOT FOUND")
print("\nMouse:", json.dumps(mouse, indent=2) if mouse else "NOT FOUND")

# Match policies
speaker_cat = speaker.get("category", "") if speaker else ""
mouse_cat = mouse.get("category", "") if mouse else ""
print(f"\nSpeaker category: {speaker_cat}")
print(f"Mouse category: {mouse_cat}")

# Find matching policies
if isinstance(policies_data, dict):
    print("\nPolicies structure (keys):", list(policies_data.keys()))
    for k, v in policies_data.items():
        print(f"\n--- Policy: {k} ---")
        print(json.dumps(v, indent=2))
elif isinstance(policies_data, list):
    for p in policies_data:
        cat = p.get("category", p.get("type", ""))
        print(f"\nPolicy for '{cat}':", json.dumps(p, indent=2))

